// Resolve Google Drive URL para URL pública direta
function resolveUrl(url) {
  if (!url) return null;
  const match = url.match(/drive\.google\.com\/(?:file\/d\/|open\?id=)([^/?&]+)/);
  if (match) return `https://lh3.googleusercontent.com/d/${match[1]}`;
  return url;
}

// Converte data/hora de Brasília (UTC-3) para Unix timestamp UTC
function toUtcTimestamp(date, time) {
  const t = time || '09:00';
  const [y, m, d] = date.split('-').map(Number);
  const [h, min] = t.split(':').map(Number);
  return Math.floor(Date.UTC(y, m - 1, d, h + 3, min, 0) / 1000);
}

const body = $input.first().json.body;

if (!body.page_id || !body.page_token) {
  throw new Error('page_id e page_token são obrigatórios');
}

// Resolve URLs do carrossel
const mediaUrls = Array.isArray(body.media_urls)
  ? body.media_urls.map(u => resolveUrl(u)).filter(Boolean)
  : [];

return [{
  json: {
    content_id:    body.content_id,
    content_type:  body.content_type || 'imagem',
    caption:       body.caption || '',
    image_url:     resolveUrl(body.image_url),
    media_urls:    mediaUrls,
    scheduled_ts:  toUtcTimestamp(body.scheduled_date, body.scheduled_time),
    page_id:       body.page_id,
    page_token:    body.page_token,
    ig_account_id: body.ig_account_id || null,
  }
}];

// ── Helpers ───────────────────────────────────────────────────────────────
function parseJson(data) {
  if (typeof data === 'string') { try { return JSON.parse(data); } catch(e) { return {}; } }
  return data || {};
}

async function postForm(url, params) {
  const resp = await $helpers.httpRequest({
    method: 'POST',
    url,
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: params.toString(),
    returnFullResponse: true,
  });
  return parseJson(resp.body);
}

// Cria container de mídia no Instagram e publica
async function igCreateAndPublish(igId, containerParams, publishToken, GRAPH) {
  const containerResp = await postForm(`${GRAPH}/${igId}/media`, containerParams);
  if (containerResp.error) return { post_id: null, error: containerResp.error.message };
  if (!containerResp.id)   return { post_id: null, error: 'Instagram não retornou creation_id' };

  const publishParams = new URLSearchParams({
    creation_id:  containerResp.id,
    access_token: publishToken,
  });
  const publishResp = await postForm(`${GRAPH}/${igId}/media_publish`, publishParams);
  return {
    post_id: publishResp.id || containerResp.id,
    error:   publishResp.error?.message || null,
  };
}

// ── Contexto ───────────────────────────────────────────────────────────────
const prep      = $('Preparar Dados').first().json;
const tokenResp = $input.first().json;
const GRAPH     = 'https://graph.facebook.com/v21.0';
const pageToken = tokenResp.access_token || prep.page_token;
const now       = Math.floor(Date.now() / 1000);
const type      = prep.content_type;  // imagem | carrossel | reel | story
const isStory   = type === 'story';

// Validação de tempo (stories no Facebook publicam imediatamente, sem restrição)
if (!isStory && prep.scheduled_ts < now + 600) {
  const msg = 'Data de agendamento deve ser pelo menos 10 minutos no futuro';
  return [{ json: { content_id: prep.content_id, update: {},
    facebook: { post_id: null, error: msg }, instagram: { post_id: null, error: msg } }}];
}

// ── FACEBOOK ───────────────────────────────────────────────────────────────
let fbPostId = null, fbError = null;
try {
  if (isStory && prep.image_url) {
    // Story Facebook → publica IMEDIATAMENTE (Meta não suporta agendamento de stories)
    const p = new URLSearchParams({ url: prep.image_url, access_token: pageToken });
    const r = await postForm(`${GRAPH}/${prep.page_id}/photo_stories`, p);
    fbPostId = r.post_id || r.id || null;
    fbError  = r.error?.message || null;

  } else if (type === 'reel' && prep.image_url) {
    // Reel Facebook → agendar vídeo
    const p = new URLSearchParams({
      file_url:               prep.image_url,
      published:              'false',
      scheduled_publish_time: String(prep.scheduled_ts),
      access_token:           pageToken,
    });
    if (prep.caption) p.append('description', prep.caption);
    const r = await postForm(`${GRAPH}/${prep.page_id}/videos`, p);
    fbPostId = r.id || null;
    fbError  = r.error?.message || null;

  } else {
    // Imagem ou Carrossel → post de foto agendado (usa a 1ª imagem no carrossel)
    const imgUrl = (type === 'carrossel' && prep.media_urls?.length)
      ? prep.media_urls[0]
      : prep.image_url;

    const endpoint = imgUrl
      ? `${GRAPH}/${prep.page_id}/photos`
      : `${GRAPH}/${prep.page_id}/feed`;

    const p = new URLSearchParams({
      published:              'false',
      scheduled_publish_time: String(prep.scheduled_ts),
      access_token:           pageToken,
    });
    if (imgUrl) {
      p.append('url',     imgUrl);
      p.append('caption', prep.caption);
    } else {
      p.append('message', prep.caption);
    }

    const r = await postForm(endpoint, p);
    fbPostId = r.id || null;
    fbError  = r.error?.message || null;
  }
} catch(e) {
  fbError = String(e.message);
}

// ── INSTAGRAM ──────────────────────────────────────────────────────────────
let igPostId = null, igError = null;

if (prep.ig_account_id) {
  try {
    if (type === 'carrossel' && prep.media_urls?.length >= 2) {
      // Carrossel Instagram:
      // 1) Criar container para cada imagem (is_carousel_item=true)
      // 2) Criar container CAROUSEL com a lista de IDs
      // 3) Publicar
      const itemIds = [];
      for (const imgUrl of prep.media_urls) {
        const p = new URLSearchParams({
          image_url:         imgUrl,
          is_carousel_item:  'true',
          access_token:      pageToken,
        });
        const r = await postForm(`${GRAPH}/${prep.ig_account_id}/media`, p);
        if (r.error) { igError = r.error.message; break; }
        if (r.id)    itemIds.push(r.id);
      }

      if (!igError && itemIds.length >= 2) {
        const carouselParams = new URLSearchParams({
          media_type:             'CAROUSEL',
          children:               itemIds.join(','),
          caption:                prep.caption,
          published:              'false',
          scheduled_publish_time: String(prep.scheduled_ts),
          access_token:           pageToken,
        });
        const result = await igCreateAndPublish(
          prep.ig_account_id, carouselParams, pageToken, GRAPH
        );
        igPostId = result.post_id;
        igError  = result.error;
      }

    } else if (type === 'reel' && prep.image_url) {
      // Reel Instagram
      const p = new URLSearchParams({
        media_type:             'REELS',
        video_url:              prep.image_url,
        caption:                prep.caption,
        published:              'false',
        scheduled_publish_time: String(prep.scheduled_ts),
        access_token:           pageToken,
      });
      const result = await igCreateAndPublish(prep.ig_account_id, p, pageToken, GRAPH);
      igPostId = result.post_id;
      igError  = result.error;

    } else if (isStory && prep.image_url) {
      // Story Instagram → agendado com scheduled_publish_time
      const p = new URLSearchParams({
        media_type:             'STORIES',
        image_url:              prep.image_url,
        published:              'false',
        scheduled_publish_time: String(prep.scheduled_ts),
        access_token:           pageToken,
      });
      const result = await igCreateAndPublish(prep.ig_account_id, p, pageToken, GRAPH);
      igPostId = result.post_id;
      igError  = result.error;

    } else if (prep.image_url) {
      // Imagem única
      const p = new URLSearchParams({
        image_url:              prep.image_url,
        caption:                prep.caption,
        published:              'false',
        scheduled_publish_time: String(prep.scheduled_ts),
        access_token:           pageToken,
      });
      const result = await igCreateAndPublish(prep.ig_account_id, p, pageToken, GRAPH);
      igPostId = result.post_id;
      igError  = result.error;
    }
  } catch(e) {
    igError = String(e.message);
  }
}

// ── Payload para Supabase ──────────────────────────────────────────────────
const update = {};
if (fbPostId) update.facebook_post_id  = fbPostId;
if (igPostId) update.instagram_post_id = igPostId;
if (fbPostId || igPostId) update.status = 'published';

return [{ json: {
  content_id: prep.content_id,
  update,
  facebook:  { post_id: fbPostId, error: fbError },
  instagram: { post_id: igPostId, error: igError },
}}];

